import tailwindcss from '@tailwindcss/vite';
import react from '@vitejs/plugin-react';
import path from 'path';
import { defineConfig } from 'vite';
import { VitePWA } from 'vite-plugin-pwa';

// Avista PWA: React 19 + Tailwind v4. The manifest and service worker are
// generated by vite-plugin-pwa, so the "Instalar App" button and the offline
// indicator in the header work on Android, desktop and (via guide) iOS.
export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
    VitePWA({
      registerType: 'autoUpdate',
      includeAssets: ['favicon.svg', 'apple-touch-icon.png', 'images/*.jpg'],
      manifest: {
        name: 'Avista · Fundación Integra',
        short_name: 'Avista',
        description:
          'IA pedagógica que transforma notas, audios y fotos de aula en bitácoras, recomendaciones con evidencia y reportes de dirección.',
        lang: 'es-CL',
        start_url: '/',
        scope: '/',
        display: 'standalone',
        background_color: '#fdf9f4',
        theme_color: '#fdf9f4',
        icons: [
          { src: 'icon-192.png', sizes: '192x192', type: 'image/png' },
          { src: 'icon-512.png', sizes: '512x512', type: 'image/png' },
          { src: 'icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
        ],
      },
      workbox: {
        globPatterns: ['**/*.{js,css,html,svg,png,jpg,woff2}'],
        // Never cache the backend REST API: always fresh data.
        navigateFallbackDenylist: [/^\/api/, /^\/health/, /^\/docs/],
      },
    }),
  ],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, '.'),
    },
  },
  server: {
    port: 5173,
    // Optional proxy to the local FastAPI backend (run_local.ps1 starts it on :8000).
    proxy: {
      '/api': {
        target: 'http://localhost:8000',
        changeOrigin: true,
        rewrite: (p) => p.replace(/^\/api/, ''),
      },
    },
  },
});
